const needsFirstLab=!labs.some(l=>l.id===knownLab.id);if(needsFirstLab){labs.unshift(JSON.parse(JSON.stringify(knownLab)));saveState()}
function showToast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>el.classList.remove('show'),2500)}
function taskIcon(i){return i%3===1?icons.scope:i%3===2?icons.spark:icons.flask}
function setRole(next){const authenticated=window.learningAnalytics?.user;if(authenticated&&authenticated.role!==next)return;role=next;page=next==='admin'?'admin':'home';document.querySelectorAll('.role-btn').forEach(b=>b.classList.toggle('active',b.dataset.role===role));render()}
function navItems(){const analytics=['analytics',icons.task,role==='admin'?'Оқу аналитикасы':'Менің нәтижелерім'];return role==='admin'?[['admin',icons.home,'Шолу'],['manage',icons.flask,'Зертханалық жұмыстар'],['tasks-admin',icons.task,'Тапсырмалар'],['students',icons.users,'Студенттер'],['micro-admin',icons.scope,'Микроскоп'],['reports',icons.task,'Нәтижелер'],analytics]:[['home',icons.home,'Басты бет'],['labs',icons.flask,'Зертханалық жұмыстар'],['microscope',icons.scope,'Микроскоп'],['tasks',icons.task,'Тапсырмалар'],analytics]}
function drawNav(){sideNav.innerHTML=navItems().map(([key,icon,label])=>'<button class="nav-btn '+((page===key||(page==='equipment'&&key==='manage')||((page==='microphotos')&&key==='micro-admin')||(page==='quiz-editor'&&key==='tasks-admin'))?'active':'')+'" data-page="'+key+'">'+icon+'<span>'+label+'</span></button>').join('')}
