function resultHtml(lab,r){if(lab?._answerKeyHidden)return '<div class="result-grid"><div class="result-box"><h4>Құрал-жабдықтар · '+r.equipmentCorrect+'/'+r.equipmentTotal+' дұрыс</h4><p>Артық таңдау: '+(r.extraEquipmentCount||0)+' · Өткізіп алынды: '+(r.missingEquipmentCount||0)+'</p></div><div class="result-box"><h4>Жұмыс барысы · '+r.stepsInPlace+'/'+r.stepsTotal+' дұрыс ретпен</h4><p>Артық кезең: '+(r.extraStepsCount||0)+' · Өткізіп алынды: '+(r.missingStepsCount||0)+'<br>Кезең реті: '+(r.wrongOrder?'Қайта қарау керек':'Дұрыс')+'</p></div></div><div class="assignment-details" style="margin-top:10px"><b>Жалпы нәтиже:</b> '+r.score+'/'+r.total+' ұпай</div>';const list=xs=>(xs||[]).length?xs.map(escapeHtml).join('<br>'):'Жоқ';return '<div class="result-grid"><div class="result-box"><h4>Құрал-жабдықтар · '+r.equipmentCorrect+'/'+r.equipmentTotal+' дұрыс</h4><p><b>Дұрыс таңдалды:</b> '+list(r.correctEquipment)+'<br><b>Артық таңдалды:</b> '+list(r.extraEquipment)+'<br><b>Өткізіп алдыңыз:</b> '+list(r.missingEquipment)+'</p></div><div class="result-box"><h4>Жұмыс барысы · '+r.stepsInPlace+'/'+r.stepsTotal+' дұрыс ретпен</h4><p><b>Дұрыс кезеңдер:</b> '+list(r.correctStepsSelected)+'<br><b>Артық кезеңдер:</b> '+list(r.extraSteps)+'<br><b>Өткізіп алдыңыз:</b> '+list(r.missingSteps)+'<br><b>Таңдалған рет:</b> '+list(r.selectedSteps)+'<br><b>Рет бағасы:</b> '+(r.wrongOrder?'Кезеңдер қате ретпен таңдалды':'Таңдалған кезеңдердің реті дұрыс')+'</p></div></div><div class="assignment-details" style="margin-top:10px"><b>Жалпы нәтиже:</b> '+r.score+'/'+r.total+' ұпай</div>'}
