function moveStep(index,direction){const lab=labs.find(l=>l.id===activeLabId);if(!lab)return;const a=getAttempt(lab.id),order=a.stepOrder.slice(),next=index+(direction==='up'?-1:1);if(next<0||next>=order.length)return;[order[index],order[next]]=[order[next],order[index]];a.stepOrder=order;a.result=null;attempts[lab.id]=a;saveState();renderLabDetail()}
