function handleMicroscopeClick(el){if(!el)return false;if(el.dataset.microscopeLab){if(labs.some(l=>l.id===el.dataset.microscopeLab)){activeMicroscopeLabId=el.dataset.microscopeLab;render()}return true}if(el.dataset.microscopeSlide!==undefined){const lab=labs.find(l=>l.id===activeMicroscopeLabId),state=lab&&microscopeStateFor(lab),index=Number(el.dataset.microscopeSlide);if(lab&&attempts[lab.id]?.result&&lab.micrographs?.[index]){state.photoIndex=index;render()}return true}if(el.dataset.objective){const lab=labs.find(l=>l.id===activeMicroscopeLabId),state=lab&&microscopeStateFor(lab);if(!state)return true;if(el.dataset.objective==='100x'&&!state.oil){showToast('100× объектив үшін алдымен иммерсиялық май жағыңыз');document.querySelector('[data-oil-toggle]')?.classList.add('needs-oil');return true}state.objective=el.dataset.objective;render();return true}if(el.hasAttribute('data-oil-toggle')){const lab=labs.find(l=>l.id===activeMicroscopeLabId),state=lab&&microscopeStateFor(lab);if(!state)return true;state.oil=!state.oil;if(!state.oil&&state.objective==='100x')state.objective='40x';render();return true}if(el.hasAttribute('data-fit-specimen')){const lab=labs.find(l=>l.id===activeMicroscopeLabId),state=lab&&microscopeStateFor(lab);if(state){state.objective='4x';state.stageX=0;state.stageY=0;render();showToast('Толық фото 4× объективте көрсетілді')}return true}if(el.hasAttribute('data-light-toggle')){const lab=labs.find(l=>l.id===activeMicroscopeLabId),state=lab&&microscopeStateFor(lab);if(state){state.light=!state.light;render()}return true}if(el.dataset.stageMove){const lab=labs.find(l=>l.id===activeMicroscopeLabId),state=lab&&microscopeStateFor(lab);if(!state)return true;const delta=el.dataset.stageMove==='center'?null:5;if(delta===null){state.stageX=0;state.stageY=0}else if(el.dataset.stageMove==='left')state.stageX=Math.max(-35,state.stageX-delta);else if(el.dataset.stageMove==='right')state.stageX=Math.min(35,state.stageX+delta);else if(el.dataset.stageMove==='up')state.stageY=Math.max(-35,state.stageY-delta);else if(el.dataset.stageMove==='down')state.stageY=Math.min(35,state.stageY+delta);render();return true}if(el.dataset.focusStep){const lab=labs.find(l=>l.id===activeMicroscopeLabId),state=lab&&microscopeStateFor(lab);if(state){state.focus=Math.max(0,Math.min(100,state.focus+Number(el.dataset.focusStep)));render()}return true}if(el.hasAttribute('data-microscope-reset')){const lab=labs.find(l=>l.id===activeMicroscopeLabId);if(lab){microscopeStates[lab.id]={objective:'4x',focus:50,brightness:72,light:true,stageX:0,stageY:0,oil:false,photoIndex:0};render();showToast('Микроскоп баптаулары қалпына келтірілді')}return true}return false}
function handleMicroscopePointerDown(event){const viewport=event.target.closest('#microscopeEyepiece');if(!viewport||event.button!==0)return;const lab=labs.find(l=>l.id===activeMicroscopeLabId);if(!lab)return;microscopeDrag={labId:lab.id,pointerId:event.pointerId,lastX:event.clientX,lastY:event.clientY,viewport};viewport.classList.add('dragging');try{viewport.setPointerCapture(event.pointerId)}catch{}event.preventDefault()}
function handleMicroscopePointerMove(event){if(!microscopeDrag)return;const lab=labs.find(l=>l.id===microscopeDrag.labId),viewport=microscopeDrag.viewport;if(!lab||!viewport)return;const rect=viewport.getBoundingClientRect(),state=microscopeStateFor(lab),zoom=microscopeZoom(state.objective),limit=Math.max(10,50-50/zoom),dx=event.clientX-microscopeDrag.lastX,dy=event.clientY-microscopeDrag.lastY;microscopeDrag.lastX=event.clientX;microscopeDrag.lastY=event.clientY;state.stageX=Math.max(-limit,Math.min(limit,state.stageX+(dx/Math.max(1,rect.width))*100/zoom));state.stageY=Math.max(-limit,Math.min(limit,state.stageY+(dy/Math.max(1,rect.height))*100/zoom));updateMicroscopeProjection()}
