function handleAssignmentChange(event){const target=event.target;if(!target.matches('[data-eq-choice],[data-step-choice]'))return;const lab=labs.find(l=>l.id===activeLabId);if(!lab)return;const a=getAttempt(lab.id),selectedEquipment=[...assignmentBody.querySelectorAll('[data-eq-choice]:checked')].map(x=>x.dataset.eqChoice),selectedSteps=[...assignmentBody.querySelectorAll('[data-step-choice]:checked')].map(x=>x.dataset.stepChoice),oldOrder=a.stepOrder||[];const equipmentChanged=target.matches('[data-eq-choice]');a.equipment=selectedEquipment;a.steps=selectedSteps;a.stepOrder=oldOrder.filter(id=>selectedSteps.includes(id)).concat(selectedSteps.filter(id=>!oldOrder.includes(id)));if(equipmentChanged)a.equipmentSaved=false;const hadResult=Boolean(a.result);a.result=null;attempts[lab.id]=a;saveState();renderLabDetail();if(hadResult)showToast('Жауабыңыз өзгерді. Нәтижені қайта тексеріңіз.')}
