content.addEventListener('input',event=>{const control=event.target.closest('[data-microscope-control]');if(!control)return;const lab=labs.find(l=>l.id===activeMicroscopeLabId),state=lab&&microscopeStateFor(lab);if(!state)return;state[control.dataset.microscopeControl]=Number(control.value);updateMicroscopeProjection()});
content.addEventListener('input',handleQuizEditorInput);content.addEventListener('input',handleQuizResponseInput);content.addEventListener('change',handleQuizEditorChange);content.addEventListener('change',event=>{const input=event.target.closest('[data-quiz-answer]');if(!input||input.type!=='radio'||!input.checked)return;quizResponses[input.dataset.quizAnswer]=Number(input.value);updateQuizAnsweredCount()});
content.addEventListener('pointerdown',handleMicroscopePointerDown);content.addEventListener('pointermove',handleMicroscopePointerMove);content.addEventListener('pointerup',handleMicroscopePointerEnd);content.addEventListener('pointercancel',handleMicroscopePointerEnd);content.addEventListener('wheel',handleMicroscopeWheel,{passive:false});
content.addEventListener('change',event=>{if(event.target.id==='eqPhotoInput'){const file=event.target.files?.[0];if(file)readImage(file,src=>{pendingEquipmentPhoto=src;const preview=document.getElementById('equipmentPhotoPreview');if(preview){preview.src=src;preview.style.display='block'}})}if(event.target.id==='micrographFile'){const file=event.target.files?.[0];if(file)readImage(file,src=>{pendingMicrographPhoto=src;const preview=document.getElementById('micrographPhotoPreview');if(preview){preview.src=src;preview.style.display='block'}})}});
assignmentBody.addEventListener('click',event=>{if(event.target.closest('#closeAssignment'))closeAssignment();else handleContentClick(event)});
assignmentBody.addEventListener('change',handleAssignmentChange);
document.querySelectorAll('.role-btn').forEach(b=>b.addEventListener('click',()=>setRole(b.dataset.role)));
document.getElementById('searchInput').addEventListener('input',event=>{searchText=event.target.value;if(role==='student'&&page==='home'&&searchText)page='labs';render()});
document.getElementById('mobileMenu').addEventListener('click',()=>document.getElementById('sidebar').classList.toggle('open'));
document.getElementById('addEquipment').addEventListener('click',()=>{editorEquipment.push({id:uid('eq'),name:'',correct:true,image:''});renderEquipmentEditor()});
document.getElementById('equipmentEditor').addEventListener('input',event=>{if(!event.target.matches('[data-eq-name]'))return;const row=event.target.closest('[data-eq-index]');if(row)editorEquipment[Number(row.dataset.eqIndex)].name=event.target.value});
document.getElementById('equipmentEditor').addEventListener('change',event=>{const row=event.target.closest('[data-eq-index]');if(!row)return;const i=Number(row.dataset.eqIndex);if(event.target.matches('[data-eq-correct]'))editorEquipment[i].correct=event.target.value==='true';if(event.target.matches('[data-eq-file]')){const file=event.target.files?.[0];if(file)readImage(file,src=>{editorEquipment[i].image=src;renderEquipmentEditor()})}});
document.getElementById('equipmentEditor').addEventListener('click',event=>{const b=event.target.closest('[data-remove-eq]');if(!b)return;editorEquipment.splice(Number(b.closest('[data-eq-index]').dataset.eqIndex),1);renderEquipmentEditor()});
document.getElementById('micrographInput').addEventListener('change',event=>{[...(event.target.files||[])].forEach(file=>readImage(file,src=>{editorMicrographs.push({id:uid('photo'),name:file.name,src});renderMicrographs()}));event.target.value=''});
document.getElementById('micrographPreview').addEventListener('click',event=>{const b=event.target.closest('[data-remove-photo]');if(!b)return;editorMicrographs.splice(Number(b.dataset.removePhoto),1);renderMicrographs()});
document.getElementById('labForm').addEventListener('submit',event=>{event.preventDefault();const id=document.getElementById('labId').value||uid('lab'),old=labs.find(l=>l.id===id),equipment=editorEquipment.map(e=>({...e,name:e.name.trim()})).filter(e=>e.name),correctLines=lines(document.getElementById('labStepsCorrect').value),extraLines=lines(document.getElementById('labStepsExtra').value),steps=correctLines.map((text,order)=>({id:uid('step'),text,correct:true,order})).concat(extraLines.map(text=>({id:uid('step'),text,correct:false,order:-1})));const safetyCriteria=lines(document.getElementById('labSafetyCriteria').value).map((text,index)=>({id:'safety-'+index,text})),microscopeCriteria=lines(document.getElementById('labMicroscopeCriteria').value).map((line,index)=>{const [label,answers='']=line.split('|');return {id:'micro-'+index,label:label.trim(),answers:answers.split(';').map(x=>x.trim()).filter(Boolean)}}).filter(x=>x.label&&x.answers.length),lab={id,title:document.getElementById('labTitle').value.trim(),objectives:document.getElementById('labObjectives').value.trim(),equipment,steps,resultText:document.getElementById('labResultText').value.trim(),micrographs:editorMicrographs,safetyCriteria,microscopeCriteria,aiGuidance:document.getElementById('labAiGuidance').value.trim(),errorVariants:lines(document.getElementById('labErrorVariants').value),scoreRules:{errorPenalty:Math.max(0,Math.min(10,Number(document.getElementById('labErrorPenalty').value)||0)),hintPenalty:Math.max(0,Math.min(10,Number(document.getElementById('labHintPenalty').value)||0))}};if(old)labs=labs.map(l=>l.id===id?lab:l);else labs.unshift(lab);delete attempts[id];if(!saveState())return;closeEditor();page=role==='admin'?'manage':'labs';render();showToast(old?'Зертханалық жұмыс жаңартылды':'Жаңа жұмыс сақталды')});
document.getElementById('closeModal').addEventListener('click',closeEditor);
document.getElementById('cancelModal').addEventListener('click',closeEditor);
document.getElementById('taskModal').addEventListener('click',event=>{if(event.target.id==='taskModal')closeEditor()});
assignmentModal.addEventListener('click',event=>{if(event.target===assignmentModal)closeAssignment()});
window.addEventListener('keydown',event=>{if(event.key==='Escape'){closeEditor();closeAssignment()}});
window.addEventListener('beforeprint',()=>{if(printTarget){content.classList.add('printing-one');content.querySelectorAll('.task-item').forEach(el=>el.classList.toggle('print-target',el.dataset.taskId===printTarget))}});
window.addEventListener('afterprint',()=>{printTarget=null;content.classList.remove('printing-one');content.querySelectorAll('.print-target').forEach(el=>el.classList.remove('print-target'))});
window.addEventListener('storage',event=>{if(event.key===storageKey){try{const incoming=event.newValue?JSON.parse(event.newValue):[];labs=Array.isArray(incoming)?incoming:[];if(!labs.some(l=>l.id===knownLab.id))labs.unshift(JSON.parse(JSON.stringify(knownLab)))}catch{return}}else if(event.key===attemptKey){try{attempts=event.newValue?JSON.parse(event.newValue):{}}catch{return}}else if(event.key===quizStorageKey){try{const incoming=event.newValue?JSON.parse(event.newValue):[];quizzes=Array.isArray(incoming)?incoming:[]}catch{return}}else if(event.key===quizAttemptKey){try{const incoming=event.newValue?JSON.parse(event.newValue):{};quizAttempts=incoming&&typeof incoming==='object'?incoming:{}}catch{return}}else if(event.key===assistantStoreKey){try{const incoming=event.newValue?JSON.parse(event.newValue):{};assistantConfig={...defaultAssistantConfig,...incoming,faqs:Array.isArray(incoming?.faqs)?incoming.faqs:defaultAssistantConfig.faqs};if(role==='admin'&&page==='assistant-admin')assistantDraft=JSON.parse(JSON.stringify(assistantConfig))}catch{return}}else return;render();if(assignmentModal.classList.contains('open')&&activeLabId)renderLabDetail()});
render();
